# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İKİ BOYUTTA VEKTÖRÜN DİK BİLEŞENLERİNE AYRILMASI</text>\n  <rect x="25" y="42" width="320" height="200" rx="10" fill="#ffffff" stroke="#cbd5e1" stroke-width="2"/>\n  <line x1="70" y1="205" x2="310" y2="205" stroke="#475569" stroke-width="2"/>\n  <text x="320" y="209" font-size="12" font-weight="bold" fill="#334155">+x</text>\n  <line x1="70" y1="205" x2="70" y2="60" stroke="#475569" stroke-width="2"/>\n  <text x="65" y="53" font-size="12" font-weight="bold" fill="#334155">+y</text>\n  <line x1="70" y1="205" x2="245" y2="92" stroke="#dc2626" stroke-width="3.5"/>\n  <polygon points="241,88 252,87 247,97" fill="#dc2626"/>\n  <text x="165" y="132" font-size="13" font-weight="bold" fill="#dc2626">A Vektörü</text>\n  <line x1="252" y1="87" x2="252" y2="205" stroke="#94a3b8" stroke-width="1.5" stroke-dasharray="4,4"/>\n  <line x1="252" y1="87" x2="70" y2="87" stroke="#94a3b8" stroke-width="1.5" stroke-dasharray="4,4"/>\n  <line x1="70" y1="205" x2="245" y2="205" stroke="#2563eb" stroke-width="3.5"/>\n  <polygon points="245,200 253,205 245,210" fill="#2563eb"/>\n  <text x="160" y="226" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">A_x = A · cos θ</text>\n  <line x1="70" y1="205" x2="70" y2="93" stroke="#16a34a" stroke-width="3.5"/>\n  <polygon points="65,95 70,86 75,95" fill="#16a34a"/>\n  <text x="122" y="80" font-size="12" font-weight="bold" fill="#15803d">A_y = A · sin θ</text>\n  <text x="108" y="198" font-size="12" font-weight="bold" fill="#0f172a">θ</text>\n  <rect x="360" y="42" width="315" height="200" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">TRİGONOMETRİK BİLEŞEN HESABI</text>\n  <text x="378" y="95" font-size="12" font-weight="bold" fill="#1e3a8a">• Yatay Bileşen (Komşu): A_x = A · cos θ</text>\n  <text x="378" y="120" font-size="12" font-weight="bold" fill="#1e3a8a">• Düşey Bileşen (Karşı): A_y = A · sin θ</text>\n  <text x="378" y="145" font-size="12" font-weight="bold" fill="#1d4ed8">• Pisagor Bağıntısı: A = kök(A_x² + A_y²)</text>\n  <rect x="378" y="162" width="280" height="66" rx="6" fill="#dbeafe" stroke="#60a5fa"/>\n  <text x="517" y="182" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">37° - 53° - 90° Özel Üçgen Oranları:</text>\n  <text x="517" y="200" text-anchor="middle" font-size="11" fill="#1e3a8a">sin 37° = cos 53° = 0,6   |   cos 37° = sin 53° = 0,8</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Örnek: A = 20 N, θ = 37° → A_x = 16 N, A_y = 12 N</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ANALİTİK (TABLO) YÖNTEMİYLE ÇOKLU VEKTÖR TOPLAMA</text>\n  <rect x="25" y="42" width="320" height="200" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="185" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">BİLEŞEN TABLOSU ÖRNEĞİ</text>\n  <text x="45" y="92" font-size="11.5" font-weight="bold" fill="#14532d">Vektör       Yatay (x)       Düşey (y)</text>\n  <line x1="42" y1="98" x2="325" y2="98" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="45" y="118" font-size="11.5" fill="#334155">F₁               +8 N             +6 N</text>\n  <text x="45" y="140" font-size="11.5" fill="#334155">F₂               -3 N             +10 N</text>\n  <text x="45" y="162" font-size="11.5" fill="#334155">F₃               +4 N             -4 N</text>\n  <line x1="42" y1="172" x2="325" y2="172" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="45" y="192" font-size="12" font-weight="bold" fill="#15803d">Toplam:   R_x = +9 N     R_y = +12 N</text>\n  <text x="185" y="222" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">R = kök(9² + 12²) = kök(81 + 144) = 15 N</text>\n  <rect x="360" y="42" width="315" height="200" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">ANALİTİK TOPLAMA ADIMLARI</text>\n  <text x="378" y="95" font-size="11.5" font-weight="bold" fill="#713f12">1. Eksenlerle açı yapan her vektör x ve y</text>\n  <text x="390" y="112" font-size="11" fill="#334155">dik bileşenlerine ayrılır.</text>\n  <text x="378" y="138" font-size="11.5" font-weight="bold" fill="#713f12">2. İşaret yönlerine (+x sağ, -x sol; +y yukarı,</text>\n  <text x="390" y="155" font-size="11" fill="#334155">-y aşağı) dikkat edilerek R_x ve R_y bulunur.</text>\n  <text x="378" y="181" font-size="11.5" font-weight="bold" fill="#713f12">3. Birbirine dik R_x ve R_y vektörlerinden</text>\n  <text x="390" y="198" font-size="11" fill="#334155">Pisagor ile R = kök(R_x² + R_y²) hesaplanır.</text>\n  <text x="517" y="225" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">Dengeleyen kuvvet: E = -R = (-R_x, -R_y)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ÖZEL AÇILI EŞİT VEKTÖRLER VE VEKTÖR FARKI (A - B)</text>\n  <rect x="25" y="42" width="320" height="200" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="185" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">ÖZEL AÇILARDA BİLEŞKE (F₁ = F₂ = F)</text>\n  <text x="42" y="94" font-size="11.5" font-weight="bold" fill="#581c87">• α = 0° (Aynı yönlü)  →  R = 2F (Maksimum)</text>\n  <text x="42" y="118" font-size="11.5" font-weight="bold" fill="#581c87">• α = 60° ise  →  R = F · kök(3)</text>\n  <text x="42" y="142" font-size="11.5" font-weight="bold" fill="#581c87">• α = 90° (Dik) ise  →  R = F · kök(2)</text>\n  <text x="42" y="166" font-size="11.5" font-weight="bold" fill="#581c87">• α = 120° ise  →  R = F</text>\n  <text x="42" y="190" font-size="11.5" font-weight="bold" fill="#581c87">• α = 180° (Zıt yönlü)  →  R = 0 (Minimum)</text>\n  <text x="185" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Açı küçüldükçe bileşke vektörün büyüklüğü artar!</text>\n  <rect x="360" y="42" width="315" height="200" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">VEKTÖRLERDE ÇIKARMA VE SKALER ÇARPIM</text>\n  <text x="378" y="95" font-size="11.5" font-weight="bold" fill="#7c2d12">• Vektörün Skaler Sayı (k) ile Çarpımı:</text>\n  <text x="388" y="113" font-size="11" fill="#334155">- k &gt; 0 ise yön değişmez, boy |k| katına çıkar.</text>\n  <text x="388" y="130" font-size="11" fill="#334155">- k &lt; 0 ise vektör 180° zıt yöne döner.</text>\n  <text x="378" y="158" font-size="11.5" font-weight="bold" fill="#7c2d12">• İki Vektörün Farkı (A - B):</text>\n  <text x="388" y="176" font-size="11" fill="#334155">Çıkarılacak vektör ters çevrilip (-B) toplanır:</text>\n  <text x="517" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#c2410c">Fark Vektörü: D = A - B = A + (-B)</text>\n  <text x="517" y="224" text-anchor="middle" font-size="10.5" fill="#9a3412">Koordinatla: A(x₁, y₁) - B(x₂, y₂) = (x₁ - x₂, y₁ - y₂)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
